-- 0007: clubs and crews, members, join requests and invites, club chat. Mirrors later-schema.js (n: 7).
CREATE TABLE IF NOT EXISTS clubs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL UNIQUE, tag TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'club', motto TEXT NOT NULL DEFAULT '', color TEXT NOT NULL, is_open BIGINT NOT NULL DEFAULT 1, leader_id BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS club_members (user_id BIGINT PRIMARY KEY, club_id BIGINT NOT NULL, role TEXT NOT NULL, joined_at BIGINT NOT NULL, muted_until BIGINT NOT NULL DEFAULT 0, hangout_at BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ix_club_members_club ON club_members(club_id);
CREATE TABLE IF NOT EXISTS club_requests (club_id BIGINT NOT NULL, user_id BIGINT NOT NULL, kind TEXT NOT NULL, created_at BIGINT NOT NULL, invited_by BIGINT, PRIMARY KEY (club_id, user_id));
CREATE INDEX IF NOT EXISTS ix_club_requests_user ON club_requests(user_id);
CREATE TABLE IF NOT EXISTS club_chat (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, club_id BIGINT NOT NULL, user_id BIGINT NOT NULL, username TEXT NOT NULL, text TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_club_chat_club ON club_chat(club_id, id);
CREATE TABLE IF NOT EXISTS club_cooldowns (user_id BIGINT PRIMARY KEY, until_ms BIGINT NOT NULL);
